
#include <stdint.h>

#include "bootloader.h"
#include "protocol.h"
#include "flash_mock.h"

/* Exact 76-byte stream generated by Python */
static const uint8_t host_stream[76] =
{
    0xAAU, 0x55U, 0x01U, 0x01U, 0x00U, 0x00U, 0x00U, 0x08U,
    0x00U, 0x00U, 0x00U, 0x10U, 0xF4U, 0xA7U, 0xFDU, 0x67U,
    0xEDU, 0xEDU, 0xD5U, 0xB0U,

    0xAAU, 0x55U, 0x01U, 0x03U, 0x00U, 0x01U, 0x00U, 0x14U,
    0x00U, 0x00U, 0x00U, 0x00U, 0x10U, 0x11U, 0x12U, 0x13U,
    0x14U, 0x15U, 0x16U, 0x17U, 0x18U, 0x19U, 0x1AU, 0x1BU,
    0x1CU, 0x1DU, 0x1EU, 0x1FU, 0xA7U, 0x6EU, 0xE4U, 0x47U,

    0xAAU, 0x55U, 0x01U, 0x04U, 0x00U, 0x02U, 0x00U, 0x00U,
    0x8CU, 0x9AU, 0x00U, 0xA8U,

    0xAAU, 0x55U, 0x01U, 0x05U, 0x00U, 0x03U, 0x00U, 0x00U,
    0xB0U, 0x38U, 0x43U, 0x2FU
};

#define HOST_STREAM_SIZE 76U

/* Debugger result variables */
volatile uint32_t stream_index = 0U;

volatile uint8_t start_state = 0xFFU;
volatile uint8_t write_state = 0xFFU;
volatile uint8_t verify_state = 0xFFU;
volatile uint8_t final_state = 0xFFU;

volatile uint8_t flash_read_result = 0xFFU;
volatile uint8_t flash_match = 0U;
volatile uint8_t transfer_test_complete = 0U;

static const uint8_t expected_firmware[16] =
{
    0x10U, 0x11U, 0x12U, 0x13U,
    0x14U, 0x15U, 0x16U, 0x17U,
    0x18U, 0x19U, 0x1AU, 0x1BU,
    0x1CU, 0x1DU, 0x1EU, 0x1FU
};

int main(void)
{
    uint8_t readback[16];
    uint32_t i;

    /* Initialize bootloader */
    Bootloader_Init();

    /* Inject all Python-generated bytes */
    for (i = 0U; i < HOST_STREAM_SIZE; i++)
    {
        Bootloader_TestInjectByte(host_stream[i]);

        stream_index = i + 1U;

        if (stream_index == 20U)
        {
            start_state = Bootloader_GetState();
        }

        if (stream_index == 52U)
        {
            write_state = Bootloader_GetState();
        }

        if (stream_index == 64U)
        {
            verify_state = Bootloader_GetState();
        }
    }

    /* Capture final bootloader state */
    final_state = Bootloader_GetState();

    /* Read firmware from simulated flash */
    flash_read_result = (uint8_t)FlashMock_Read(
        0U,
        readback,
        16U
    );

    /* Compare flash contents */
    flash_match = 1U;

    for (i = 0U; i < 16U; i++)
    {
        if (readback[i] != expected_firmware[i])
        {
            flash_match = 0U;
        }
    }

    /* Final test condition */
    if ((stream_index == HOST_STREAM_SIZE) &&
        (start_state == BL_STATE_RECEIVING) &&
        (write_state == BL_STATE_RECEIVING) &&
        (verify_state == BL_STATE_COMPLETE) &&
        (final_state == BL_STATE_COMPLETE) &&
        (flash_read_result == FLASH_OK) &&
        (flash_match == 1U))
    {
        transfer_test_complete = 1U;
    }

    /* Stop for debugger inspection */
    while (1)
    {
    }
}
